INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Algorithmus immer in einer Programmiersprache geschrieben?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch abstrakt formuliert sein"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend kodiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Algorithmus?', 3, '[{"text": "Problemlösung", "correct": true, "because": "Definiert Schritte zur Lösung"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nur ein Anwendungsfall"}, {"text": "Hardwareoptimierung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat ein guter Algorithmus?', 5, '[{"text": "Effizienz", "correct": true, "because": "Minimiert Ressourcen"}, {"text": "Klarheit", "correct": true, "because": "Leicht verständlich"}, {"text": "Farbliche Gestaltung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Algorithmus hat eine endliche Anzahl an Schritten. b) Er ist immer deterministisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kann auch nicht-deterministisch sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Entwicklung eines Algorithmus?', 4, '[{"text": "Laufzeit", "correct": false, "because": "Wichtig für Effizienz"}, {"text": "Eingabedaten", "correct": false, "because": "Grundlage der Verarbeitung"}, {"text": "Programmiereranzahl", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Algorithmus Schleifen enthalten kann?', 2, '[{"text": "Ja", "correct": true, "because": "Wiederholungen sind üblich"}, {"text": "Nein", "correct": false, "because": "Nicht ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für eine Sortierung?', 3, '[{"text": "Bubble Sort", "correct": true, "because": "Einfacher Algorithmus"}, {"text": "Lineare Suche", "correct": false, "because": "Keine Sortierung"}, {"text": "Binäre Addition", "correct": false, "because": "Andere Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Analyse eines Algorithmus?', 5, '[{"text": "Zeitkomplexität", "correct": true, "because": "Misst Laufzeit"}, {"text": "Raumkomplexität", "correct": true, "because": "Misst Speicherbedarf"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Analysefaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Algorithmen sind maschinenabhängig. b) Sie lösen Probleme schrittweise. Stimmt das?', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Abstrakt, nicht maschinenabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Algorithmus unwichtig?', 4, '[{"text": "Korrektheit", "correct": false, "because": "Muss Problem lösen"}, {"text": "Effizienz", "correct": false, "because": "Optimiert Ausführung"}, {"text": "Programmiersprachensyntax", "correct": true, "because": "Abstrakte Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ein Algorithmus eindeutig sein?', 2, '[{"text": "Ja", "correct": true, "because": "Schritte müssen klar sein"}, {"text": "Nein", "correct": false, "because": "Unklarheit unzulässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt ein effizienter Algorithmus?', 4, '[{"text": "Schnellere Ausführung", "correct": true, "because": "Weniger Zeitaufwand"}, {"text": "Geringerer Speicherbedarf", "correct": true, "because": "Optimiert Ressourcen"}, {"text": "Schönere Darstellung", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Algorithmen immer linear ablaufen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Können verzweigen oder wiederholen"}, {"text": "Ja", "correct": false, "because": "Nicht nur linear"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Algorithmusentwicklung?', 3, '[{"text": "Effizienz", "correct": true, "because": "Minimiert Ressourcen"}, {"text": "Design", "correct": false, "because": "Sekundär"}, {"text": "Schnellschreibung", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Algorithmus kann rekursiv sein. b) Er braucht immer Schleifen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schleifen nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein ineffizienter Algorithmus?', 5, '[{"text": "Hohe Laufzeit", "correct": true, "because": "Verlangsamt Prozesse"}, {"text": "Großer Speicherbedarf", "correct": true, "because": "Verschwendet Ressourcen"}, {"text": "Einfache Implementierung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Algorithmus unwichtig?', 3, '[{"text": "Endlichkeit", "correct": false, "because": "Muss terminiert sein"}, {"text": "Klarheit", "correct": false, "because": "Verständnis nötig"}, {"text": "Programmierername", "correct": true, "because": "Kein funktionaler Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Algorithmus mehrere Lösungen haben?', 3, '[{"text": "Ja", "correct": true, "because": "Je nach Problem möglich"}, {"text": "Nein", "correct": false, "because": "Nicht ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Algorithmus deterministisch sein muss?', 2, '[{"text": "Nein", "correct": true, "because": "Nicht-deterministisch möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel je nach Einsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Algorithmus wähle ich für eine schnelle Suche?', 4, '[{"text": "Binäre Suche", "correct": true, "because": "Effizient bei sortierten Daten"}, {"text": "Bubble Sort", "correct": false, "because": "Sortierung, nicht Suche"}, {"text": "Lineare Suche", "correct": false, "because": "Langsamer"}]');